import{_ as e}from"./chunks/connect.BTLErx-Y.js";import{_ as t,o as r,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const _=JSON.parse('{"title":"Подключение и вход","description":"","frontmatter":{"pageId":"players/connect","contentRevision":1},"headers":[],"relativePath":"ru/players/connect.md","filePath":"ru/players/connect.md"}'),n={name:"ru/players/connect.md"};function s(l,a,c,p,d,h){return r(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="подключение-и-вход" tabindex="-1">Подключение и вход <a class="header-anchor" href="#подключение-и-вход" aria-label="Permalink to &quot;Подключение и вход&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+e+'" alt="Две колонии подключаются к серверу по защищённому соединению." width="960" height="440"><p class="wiki-caption">Две колонии подключаются к серверу по защищённому соединению.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>В меню <strong>Мультиплеер</strong> добавь host и порт (по умолчанию 25560). Адрес выдаёт администратор; браузерный URL панели и игровой endpoint не обязательно одинаковы. Если сервер защищён общим паролем, он нужен дополнительно к личному входу.</p><p>Steam-вход использует билет Steam. Парольный вход доступен только когда сервер разрешил его; логин и пароль относятся к этому серверу. Новый сертификат запомнится после доверия. При изменении pin сначала спроси администратора, действительно ли сертификат заменён.</p><p>После входа сервер либо загружает сохранённую колонию, либо предлагает создать новую, либо показывает различия набора модов. Исправь указанные различия и подключись снова.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не отключай TLS ради устранения ошибки сертификата. Не передавай личные пароли через чат. При временном отказе Steam дождись повторной проверки, не создавай много новых аккаунтов.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./modpacks">Набор модов сервера</a></li><li><a href="./../admins/security-auth">TLS, вход и права</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li></ul>',12)])])}const f=t(n,[["render",s]]);export{_ as __pageData,f as default};
